  function followPath(base, path, createMissingObj = false){
    return path.reduce((a, p)=>{
      if (a == null) return null;

      if (Array.isArray(a) && !createMissingObj && (a.length <= p || a[p] == null))
        return null;    

      if (createMissingObj && a[p] == null) a[p] = {};
      
      return a[p];
    }, base);
  }

